    dp[(0, 0, 0)] = grid[0][0]  # (step, p1, p2) -> value

    for step in range(1, 2 * N + 1):
        for p1 in range(N):
            for p2 in range(N):
                if p1 < p2:
                    p1, p2 = p2, p1
                # p1 and p2 must be valid positions at this step
                if p1 > step or p2 > step or p1 < step - N + 1 or p2 < step - N + 1:
                    continue
                if step >= 2 * (N - 1) and not (p1 == N - 1 and p2 == N - 1):
                    continue

