def max_energy(beads):
    n = len(beads)
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        # Two beads: first bead head = beads[0], tail = beads[1], second bead head = beads[1], tail = beads[0]
        # Merge energy = beads[0] * beads[1] * beads[0] = beads[0]^2 * beads[1]
        return beads[0] * beads[0] * beads[1] + beads[1] * beads[1] * beads[0]

    # dp[i][j] = maximum energy to merge beads from i to j (inclusive) in a linear chain
    dp = [[0] * n for _ in range(n)]

    # Fill the table
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = 0
            for k in range(i, j - 1):
                # Merge chain i..k and chain k+1..j
                if k - i >= 1:
                    left = dp[i][k]
                else:
                    left = 0
                if j - k - 1 >= 1:
                    right = dp[k+1][j]
                else:
                    right = 0
                energy = left + right + beads[i] * beads[k] * beads[j]
                if energy > dp[i][j]:
                    dp[i][j] = energy

    return dp[0][n-1]
