    cutoff_score = sorted_applicants[cutoff_index - 1][1]

    # Collect all applicants whose score is >= cutoff_score
    # We use the sorted list to ensure correct ordering, but we need to include ALL who meet the score
    # That is, if multiple at the boundary score exist beyond cutoff_index, they all are included
    qualified = []
    for applicant in sorted_applicants:
        if applicant[1] >= cutoff_score:
            qualified.append(applicant)
        else:
            # Since sorted by score descending, once we go below cutoff_score, we can stop
