def decode(encoded: str, original: str, message: str) -> str:
    # Check if lengths match
    if len(encoded) != len(original):
        return "Failed"

    # Build the mapping from encoded to original
    mapping = {}
    # Also track which original letters are already mapped to (to detect contradictions)
    # We need: encoded char -> original char mapping
    # Contradiction 1: same encoded char maps to different original chars
    # Contradiction 2: different encoded chars map to the same original char (since it should be a bijection)

    encoded_to_original = {}
    original_to_encoded = {}  # To check if an original letter is already used

    for enc_char, orig_char in zip(encoded, original):
        if enc_char in encoded_to_original:
            if encoded_to_original[enc_char] != orig_char:
                return "Failed"
        else:
            encoded_to_original[enc_char] = orig_char

        if orig_char in original_to_encoded:
            if original_to_encoded[orig_char] != enc_char:
                return "Failed"
        else:
            original_to_encoded[orig_char] = enc_char

    # Now, we need to check if all letters in the alphabet are covered
    # According to the problem, if not all letters are represented in the mapping, return "Failed"
    # We assume the alphabet is A-Z (26 letters)
    alphabet = set("ABCDEFGHIJKLMNOPQRSTUVWXYZ")
    mapped_encoded = set(encoded_to_original.keys())
    mapped_original = set(original_to_encoded.keys())

    # Check if the mapping covers the entire alphabet
    if mapped_encoded != alphabet or mapped_original != alphabet:
        return "Failed"

    # Now decode the message
    decoded = []
    for char in message:
        if char in encoded_to_original:
            decoded.append(encoded_to_original[char])
        else:
            # If a character in the message is not in the mapping, it's a failure
            return "Failed"

    return "".join(decoded)
