def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0
    quotient = y0 // x0
    count = 0
    for a in range(1, int(quotient ** 0.5) + 1):
        if quotient % a != 0:
            continue
        b = quotient // a
        if a > b:
            continue
        from math import gcd
        if gcd(a, b) != 1:
            continue
        if a == b:
            count += 1
        else:
            count += 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""
    if len(inorder) != len(postorder):
        return ""

    result = []
    index_map = {val: idx for idx, val in enumerate(inorder)}

    def build(post_start, post_end, in_start, in_end):
        if post_start > post_end or in_start > in_end:
            return None

        root_val = postorder[post_end]
        root_in_index = index_map[root_val]

        left_size = root_in_index - in_start
        right_size = in_end - root_in_index

        build(post_start, post_start + left_size - 1, in_start, root_in_index - 1)
        result.append(root_val)
        build(post_start + left_size, post_end - 1, root_in_index + 1, in_end)

    build(0, len(postorder) - 1, 0, len(inorder) - 1)
    return ''.join(result)

