def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    visited = {A}
    queue = deque([(A, 0)])
    max_steps = 10

    while queue:
        current, steps = queue.popleft()

        if steps > max_steps:
            break

        # Try all possible string transformations
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                transformed = current[:idx] + tgt + current[idx + len(src):]
                if transformed == B:
                    return steps + 1
                if transformed not in visited:
                    visited.add(transformed)
                    queue.append((transformed, steps + 1))
                start = idx + 1

