def remaining_trees_after_clearing(l: int, areas: list) -> int:
    # If no areas are cleared, all trees remain
    if not areas:
        return l

    # Validate road length
    if l < 0:
        return 0

    # Filter and clip areas to valid range [0, l-1]
    valid_areas = []
    for start, end in areas:
        # Clamp to valid range
        clamped_start = max(0, start)
        clamped_end = min(l - 1, end)

        # Skip invalid areas (start > end after clamping or original invalid)
        if start > end:
            continue
        if clamped_start > clamped_end:
            continue

        valid_areas.append((clamped_start, clamped_end))

    if not valid_areas:
        return l

    # Sort by start time
    valid_areas.sort(key=lambda x: x[0])

    # Merge overlapping intervals
    merged = []
    for start, end in valid_areas:
        if merged and start <= merged[-1][1] + 1:
            # Overlapping or adjacent, merge
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

    # Calculate total cleared trees
    total_cleared = 0
    for start, end in merged:
        total_cleared += end - start + 1

    remaining = l - total_cleared
    return max(0, remaining)
