def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0:
        return 0

    if not herbs:
        return 0

    # dp[t] will store the maximum value achievable with time t
    # Initialize with zeros
    dp = [0] * (T + 1)

    for i in range(M):
        time_needed, value = herbs[i]
        # Traverse from T down to time_needed to avoid using the same herb twice
        for t in range(T, time_needed - 1, -1):
            prev_value = dp[t - time_needed]
            if prev_value + value > dp[t]:
                dp[t] = prev_value + value

    return dp[T]
