def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V <= 0:
        return 0
    if n <= 0 or not volumes:
        return V

    # Ensure n and len(volumes) are consistent; use the first n elements if n is less
    if n < len(volumes):
        items = volumes[:n]
    else:
        items = volumes

    # Remove items that are larger than V because they can never fit
    items = [v for v in items if v <= V]

    # If no items fit, return V
    if not items:
        return V

    # dp[i] represents whether it is possible to achieve volume i
    # Initialize dp[0] = True, all others False
    dp = [False] * (V + 1)
    dp[0] = True

    for volume in items:
        # Traverse backwards to avoid using the same item multiple times in 0/1 knapsack
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be achieved
    max_occupied = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_occupied = i
            break

    return V - max_occupied

