def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Compute Longest Increasing Subsequence ending at each index
    lis_right = [0] * n
    for i in range(n):
        lis_right[i] = 1
        for j in range(i):
            if heights[j] < heights[i]:
                lis_right[i] = max(lis_right[i], lis_right[j] + 1)

    # Compute Longest Decreasing Subsequence starting at each index
    # (equivalently, LIS from the right)
    lis_left = [0] * n
    for i in range(n - 1, -1, -1):
        lis_left[i] = 1
        for j in range(i + 1, n):
            if heights[i] > heights[j]:
                lis_left[i] = max(lis_left[i], lis_left[j] + 1)

    # The maximum length of the choir formation is the maximum over all i of:
    # lis_right[i] + lis_left[i] - 1 (the peak at position i is counted twice)
    max_choir_length = max(lis_right[i] + lis_left[i] - 1 for i in range(n))

    return n - max_choir_length
